"""Ask local model node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory


class AskLocalModelNode(Node):
    """Ask one question on your local Ollama server; returns one answer."""

    node_type: ClassVar[str] = 'ask_local_model_node'
    display_name: ClassVar[str] = 'Ask local model'
    default_alias: ClassVar[str] = 'Ask local model'
    description: ClassVar[str] = 'Ask one question on your local Ollama server; returns one answer'
    category: ClassVar[str] = NodeCategory.AI
    primary_family: ClassVar[str] = 'Complex'
    tags: ClassVar[List[str]] = ['local', 'Ollama', 'question', 'JSON']
    icon_name: ClassVar[str] = 'message-circle'
    color_hint: ClassVar[str] = 'violet'
    group: ClassVar[Optional[str]] = None
    selector_section: ClassVar[Optional[str]] = 'AI'
    input_ports: ClassVar[List[str]] = ['input', 'context']
    output_ports: ClassVar[List[str]] = ['default', 'details']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Question', 'description': '', 'data_type': 'string', 'required': True, 'sources': ['upstream', 'vault', 'configured']}, 'context': {'name': 'Context', 'description': '', 'data_type': 'string', 'required': False, 'sources': ['upstream', 'vault', 'configured']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Answer', 'description': 'The final answer as text; JSON mode still returns text', 'data_type': 'string', 'required': True, 'to': ['downstream', 'vault'], 'pass_through': True}, 'details': {'name': 'Run details', 'description': 'Model, token counts, wall time and server durations; no prompt or thinking trace', 'data_type': 'var', 'required': False, 'to': ['vault']}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Configured', 'input_vault_key': '', 'input': '', 'context_source': 'Configured', 'context_vault_key': '', 'context': '', 'model': '', 'timeout': 180, 'reply_json': False, 'thinking': False, 'num_ctx': 8192, 'temperature': 0.2, 'max_tokens': 2048, 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': '', 'details_vault_write': False, 'details_vault_key': '', 'details_vault_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Input source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Required Inputs'}, 'input_vault_key': {'type': 'string', 'label': 'Input Vault key', 'required': False, 'tab': 'Source', 'section': 'Required Inputs', 'vault_type': 'string', 'visible_when': {'input_source': 'Vault'}}, 'input': {'type': 'multiline', 'label': 'Question', 'preview': True, 'height': 5, 'description': 'One question, no tools or history. Optional Context is data, not instructions.', 'tab': 'Parameters', 'visible_when': {'input_source': 'Configured'}}, 'context_source': {'type': 'select', 'label': 'Context source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Optional Inputs'}, 'context_vault_key': {'type': 'string', 'label': 'Context Vault key', 'required': False, 'tab': 'Source', 'section': 'Optional Inputs', 'vault_type': 'string', 'visible_when': {'context_source': 'Vault'}}, 'context': {'type': 'multiline', 'label': 'Context', 'preview': True, 'height': 5, 'description': 'Optional facts; max 8,000 characters within the 20,000-character question limit.', 'tab': 'Parameters', 'visible_when': {'context_source': 'Configured'}}, 'model': {'type': 'string', 'presentation': 'local_model', 'label': 'Model override', 'placeholder': 'Blank = Options default', 'tab': 'Parameters'}, 'timeout': {'type': 'integer', 'label': 'Stop after (seconds)', 'min': 10, 'max': 600, 'description': 'Includes loading and waiting. A timeout stops waiting; no automatic retry.', 'tab': 'Parameters'}, 'reply_json': {'type': 'boolean', 'label': 'Reply as JSON', 'description': 'Returns JSON text. Use Check reply for expected fields.', 'tab': 'Parameters'}, 'thinking': {'type': 'boolean', 'label': 'Thinking', 'description': 'Off by default. Only the final answer is returned.', 'tab': 'Parameters'}, 'num_ctx': {'type': 'integer', 'label': 'Context window (tokens)', 'min': 512, 'max': 262144, 'description': 'Larger windows use more memory. Character caps do not guarantee token fit.', 'tab': 'Parameters'}, 'temperature': {'type': 'number', 'label': 'Temperature', 'min': 0, 'max': 2, 'tab': 'Parameters'}, 'max_tokens': {'type': 'integer', 'label': 'Max output tokens', 'min': 1, 'max': 8192, 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'settings_invalid', 'description': 'Check the local server URL and default model in Options.', 'retryable': False}, {'code': 'invalid_config', 'description': 'Check the local-model inputs, limits and Vault outputs.', 'retryable': False}, {'code': 'server_unreachable', 'description': 'Start Ollama or check its URL in Options.', 'retryable': False}, {'code': 'model_missing', 'description': 'Choose a model already installed on the server.', 'retryable': False}, {'code': 'local_model_required', 'description': 'Choose an installed local model, not a cloud model.', 'retryable': False}, {'code': 'server_busy', 'description': 'The local server is busy.', 'retryable': False}, {'code': 'timed_out', 'description': 'Stopped waiting at the time limit.', 'retryable': False}, {'code': 'server_error', 'description': 'The local server could not finish the request.', 'retryable': False}, {'code': 'response_too_large', 'description': 'The local server response or answer is too large.', 'retryable': False}, {'code': 'incomplete_reply', 'description': 'The local server did not finish the answer.', 'retryable': False}, {'code': 'invalid_response', 'description': 'The local server did not return a valid answer.', 'retryable': False}, {'code': 'thinking_unsupported', 'description': 'This model cannot honour the selected thinking setting.', 'retryable': False}, {'code': 'text_too_long', 'description': 'The assembled question is too long.', 'retryable': False}, {'code': 'context_too_long', 'description': 'The Context is too long.', 'retryable': False}]

    # Optional Context has an explicit off state, as in Ask Hermes. This is a
    # disabled input, not an additional source execute() could read from.
    default_config['context_source'] = 'Not used'
    config_schema['context_source']['options'].insert(0, 'Not used')

    async def execute(self, context: NodeContext) -> None:
        from ...configuration_manager import DEFAULT_SETTINGS
        from ...integrations import local_model
        from ...node_errors import NodeError
        try:
            local_model.validate_config(self.config)
            question = local_model.question_text(self.config, context)
            def setting(key):
                return context.get_setting(key) if context.get_setting else DEFAULT_SETTINGS[key]
            result = await local_model.ask(
                base_url=setting('local_model_server_url'),
                model=self.config['model'].strip() or setting('local_model_default_model'),
                question=question, timeout=self.config['timeout'],
                reply_json=self.config['reply_json'], thinking=self.config['thinking'],
                num_ctx=self.config['num_ctx'], temperature=self.config['temperature'],
                max_tokens=self.config['max_tokens'])
        except NodeError as exc:
            context.signal_error(exc)
            return
        if self.config['details_vault_write']:
            context.memory_bank.store_persistent(self.config['details_vault_key'].strip(), result.details, type_tag='var')
        if self.config['vault_write']:
            context.memory_bank.store_persistent(self.config['vault_write_key'].strip(), result.text, type_tag='string')
        forwarding = self.config['dead_drop_passthrough']
        payload = context.inputs.get('input') if forwarding else result.text
        context.signal_done({'data': {'default': payload}
                             if forwarding or self.config['transient_output'] else {}})
